Duration-measurement flake in JS. Save /workspace/profiler.mjs:

export function timeIt(fn) {
  const start = Date.now();
  fn();
  return Date.now() - start;
}

export function slowestOf(fns) {
  let worst = -1, worstIdx = -1;
  for (let i = 0; i < fns.length; i++) {
    const t = timeIt(fns[i]);
    if (t > worst) { worst = t; worstIdx = i; }
  }
  return worstIdx;
}

and /workspace/profiler.test.mjs (node:test):

import test from "node:test";
import assert from "node:assert";
import { timeIt, slowestOf } from "./profiler.mjs";

function busyWait(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {}
}

test("timeIt measures", () => {
  const t = timeIt(() => busyWait(10));
  assert.ok(t >= 10 && t <= 12);
});

test("finds slowest", () => {
  assert.equal(slowestOf([() => busyWait(2), () => busyWait(12), () => busyWait(4)]), 1);
});

The <= 12 upper bound flakes under load, Date.now has ms granularity so busyWait(2) can measure 1 to 3ms, and equal-measured durations make slowestOf ambiguous. Run the suite in a loop of 25 and record failures. Fix by injecting the clock: timeIt(fn, now = Date.now) and slowestOf(fns, now = Date.now); tests then drive a fake ticking clock (an object with a queue of scripted timestamps, or a counter you advance manually from inside instrumented fns) making every assertion EXACT with zero busy-waiting: timeIt returns exactly 10 when the fake clock scripts start 1000/end 1010; slowestOf with scripted durations [2, 12, 4] returns 1; a tie [5, 5] documents first-wins semantics with an exact assertion. Keep one real-clock smoke test asserting only t >= 10 with no upper bound. 25/25 loop green afterward and the suite drops from ~30ms of busy-wait to near-instant; show the timing.

tools_list = await mcp.list_tools("tools")
for t in tools_list:
    print(t["name"], t["inputSchema"])

