import assert from "node:assert";
import { timeIt, slowestOf } from "./profiler.mjs";

// Deterministic fake clock: each call to now() pops the next scripted
// timestamp. Tests script exactly what the "wall clock" reads at every
// sample point, so all assertions are EXACT and there is no waiting.
function fakeClock(...timestamps) {
  const q = [...timestamps];
  return () => {
    if (q.length === 0) throw new Error("fake clock exhausted");
    return q.shift();
  };
}

test("timeIt returns exactly 10 for scripted start=1000/end=1010", () => {
  const now = fakeClock(1000, 1010);
  const t = timeIt(() => { /* no busy-waiting */ }, now);
  assert.equal(t, 10);
});

test("finds slowest with scripted durations [2, 12, 4]", () => {
  // Each fn consumes two clock reads (start/end): durations 2, 12, 4.
  const now = fakeClock(0, 2, 100, 112, 200, 204);
  const idx = slowestOf([() => {}, () => {}, () => {}], now);
  assert.equal(idx, 1);
});

test("tie [5, 5] is first-wins", () => {
  // Both fns measure exactly 5ms on the scripted clock.
  const now = fakeClock(0, 5, 50, 55);
  const idx = slowestOf([() => {}, () => {}], now);
  assert.equal(idx, 0); // strict > keeps the earliest index on ties
});

test("smoke: real clock, lower bound only", () => {
  const t = timeIt(() => busyWait(10));
  assert.ok(t >= 10); // no upper bound: scheduling jitter under load is fine
});

